/**
 * One scenario per check of document-filing-build-standard, for Cost Desk.
 *
 * Generated by `npx @aipathway/conformance init document-filing-build-standard`,
 * then filled in. The checks themselves are fetched at run time from
 * https://aipathway.com.au/explore-ai/document-filing-build-standard; what is
 * here is the world each check starts in, how the build is driven, and what
 * "held" means.
 *
 * Every holds() reads the recorded port calls (world.calls), or reads a record
 * back through a port so the read is in the trace, and returns a strict
 * true or false.
 */
import { CostWorld, KEYING_RULES, sha256 } from "./cost-world.mjs";

// ── documents, as they arrive ─────────────────────────────────────────────

const T = (hhmm, day = "2026-11-02") => `${day}T${hhmm}:00+10:00`;

const invoice = (ref, door, at, { po, number, lines = [10000, 20000], total = 30000, unreadable = [] }) => ({
  ref, door, at,
  bytes: `${door}:${ref}:tax invoice ${number} PO ${po}`,
  content: { kind: "supplier_invoice", printed: { po }, fields: { invoice_number: number, ...(total === undefined ? {} : { total }) }, lines, unreadable, supplier_name: "Coastal Timber & Hardware" },
});
const docket = (ref, door, at, { job, bare, number, date = "2026-11-01", site }) => ({
  ref, door, at,
  bytes: `${door}:${ref}:delivery docket ${number}`,
  content: { kind: "delivery_docket", printed: { ...(job ? { job } : {}), ...(bare ? { bare } : {}) }, fields: { docket_number: number, delivery_date: date }, unreadable: [], site, supplier_name: "Coastal Timber & Hardware" },
});
const doc = (ref, door, at, kind, printed, fields = {}, extra = {}) => ({
  ref, door, at,
  bytes: `${door}:${ref}:${kind}:${JSON.stringify(fields)}`,
  content: { kind, printed, fields, unreadable: [], ...extra },
});

const flyer = (at) => doc("mail/flyer-ute-sale.pdf", "email", at, "flyer", {}, { headline: "Ute sale this weekend" });
const noIdDocket = (at) => docket("photo/IMG_4471.jpg", "phone_photo", at, { number: "D-900", site: "14 Banksia St" });
const bareSheet = (at) => doc("scan/job-sheet-1055.pdf", "scanner", at, "job_sheet_or_photo", { bare: "1055" }, {});
const ghostDocket = (at) => docket("mail/docket-D-905.pdf", "email", at, { job: "J-9999", number: "D-905" });
const conflictQuote = (at) => doc("form/signed-quote-Q-310.pdf", "web_form", at, "signed_quote", { job: "J-1060" }, { quote_number: "Q-310", quoted_amount: 485000, signed_date: "2026-11-01" });
const cleanInvoice = (at, door = "email", ref = "mail/INV-5531.pdf") => invoice(ref, door, at, { po: "PO-2210", number: "INV-5531" });

// ── reading the trace ─────────────────────────────────────────────────────

const of = (w, port) => w.calls.filter((c) => c.port === port);
const counts = (w) => of(w, "write_log").filter((c) => c.request?.count);
const arrivalOf = (w, ref) => counts(w).find((c) => c.request.count.ref === ref)?.response?.arrival_id ?? null;
const filingsFor = (w, aid) => of(w, "file_message").filter((c) => c.request?.arrival_id === aid);
const exceptionsFor = (w, aid) => of(w, "raise_task").filter((c) => c.request?.arrival_id === aid);
const dupsFor = (w, aid) => of(w, "write_log").filter((c) => c.request?.duplicate?.arrival_id === aid);
const writesFor = (w, aid) => of(w, "write_job").filter((c) => c.request?.arrival_id === aid);
const outcomeCalls = (w) => w.calls.filter((c) => c.port === "file_message" || c.port === "raise_task" || (c.port === "write_log" && c.request?.duplicate));
const outcomeAid = (c) => (c.port === "write_log" ? c.request.duplicate.arrival_id : c.request.arrival_id);
const exceptionId = (w, aid, reason) => exceptionsFor(w, aid).find((c) => c.request.reason === reason)?.response?.exception_id ?? null;

const describe = (w) =>
  `${w.calls.length} port call(s): ${counts(w).length} counted, ${of(w, "file_message").length} filed, ` +
  `${of(w, "raise_task").length} listed (${of(w, "raise_task").map((c) => c.request.reason).join(", ") || "none"}), ` +
  `${of(w, "write_log").filter((c) => c.request?.duplicate).length} duplicate(s), ${of(w, "write_job").length} field write(s), ${of(w, "publish_report").length} close(s)`;

async function deliverAndRun(build, world, docs, at) {
  if (at) world.at(at);
  world.deliver(docs);
  world.wakeWith({ event: "document.received" });
  await build(world.ports());
}
async function close(build, world, day, at) {
  world.at(at);
  world.wakeWith({ event: "schedule.tick", run: "daily_close", day });
  await build(world.ports());
}

const STAFF = new Set(KEYING_RULES.staff);
const REASONS = new Set(KEYING_RULES.reasons);
const KINDS = new Set(Object.keys(KEYING_RULES.kinds));

// The morning used by checks 1 and 7: one through each door.
const fiveDoors = () => [
  cleanInvoice(T("07:40")),
  docket("scan/docket-D-881.pdf", "scanner", T("07:55"), { job: "J-1042", number: "D-881" }),
  doc("photo/IMG_4480.jpg", "phone_photo", T("08:05"), "job_sheet_or_photo", { job: "J-1071" }),
  doc("form/web-301.json", "web_form", T("08:20"), "customer_form", { account: "C-302" }, { email: "lena.ruiz@example.com.au" }),
  doc("portal/S-88-statement-2026-10.pdf", "supplier_portal", T("08:30"), "statement", { account: "S-88" }, { statement_date: "2026-10-31" }),
];

export const scenarios = [
  {
    checkId: "counted-at-the-door",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = fiveDoors();
      await deliverAndRun(build, world, world.docs, T("08:45"));
    },
    holds: (w) => {
      const cs = counts(w);
      const counted = new Set(cs.map((c) => c.response.arrival_id));
      for (const d of w.docs) {
        const mine = cs.filter((c) => c.request.count.ref === d.ref);
        if (mine.length !== 1) return false;
        const { door, arrived_at, file_hash } = mine[0].request.count;
        if (door !== d.door || arrived_at !== d.at || file_hash !== sha256(d.bytes)) return false;
        const aid = mine[0].response.arrival_id;
        const countAt = w.calls.indexOf(mine[0]);
        const outcomes = outcomeCalls(w).filter((c) => outcomeAid(c) === aid);
        if (outcomes.length !== 1) return false; // counted, and then something happened to it
        if (w.calls.indexOf(outcomes[0]) < countAt) return false;
      }
      return outcomeCalls(w).every((c) => counted.has(outcomeAid(c)));
    },
    describe,
  },
  {
    checkId: "one-kind-from-a-closed-list",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = [
        cleanInvoice(T("07:30")),
        docket("scan/docket-D-882.pdf", "scanner", T("07:35"), { job: "J-1042", number: "D-882" }),
        doc("mail/PO-2230.pdf", "email", T("07:40"), "purchase_order", { job: "J-1055" }, { po_number: "PO-2230" }),
        doc("mail/signed-Q-301.pdf", "email", T("07:45"), "signed_quote", { job: "J-1042" }, { quote_number: "Q-301", quoted_amount: 1250000, signed_date: "2026-10-30" }),
        doc("photo/IMG_4481.jpg", "phone_photo", T("07:50"), "job_sheet_or_photo", { job: "J-1071" }),
        doc("mail/cert-77.pdf", "email", T("07:55"), "certificate", { job: "J-1055" }, { certificate_number: "CERT-77" }),
        doc("portal/S-88-statement.pdf", "supplier_portal", T("08:00"), "statement", { account: "S-88" }, { statement_date: "2026-10-31" }),
        doc("form/web-302.json", "web_form", T("08:05"), "customer_form", { account: "C-302" }, { phone: "0400 222 333" }),
        flyer(T("08:10")),
      ];
      await deliverAndRun(build, world, world.docs, T("08:30"));
    },
    holds: (w) => {
      for (const d of w.docs) {
        const aid = arrivalOf(w, d.ref);
        if (!aid) return false;
        const f = filingsFor(w, aid);
        if (d.content.kind === "flyer") {
          if (f.length !== 0) return false;
          const ex = exceptionsFor(w, aid);
          if (ex.length !== 1 || ex[0].request.reason !== "unknown_kind") return false;
        } else if (f.length !== 1 || f[0].request.kind !== d.content.kind) return false;
      }
      return of(w, "file_message").every((c) => KINDS.has(c.request.kind));
    },
    describe,
  },
  {
    checkId: "matched-by-the-printed-id",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = [noIdDocket(T("07:20")), bareSheet(T("07:25")), ghostDocket(T("07:30")), docket("scan/docket-D-883.pdf", "scanner", T("07:35"), { job: "J-1042", number: "D-883" })];
      await deliverAndRun(build, world, world.docs, T("08:00"));
    },
    holds: (w) => {
      const want = [["photo/IMG_4471.jpg", "no_id"], ["scan/job-sheet-1055.pdf", "two_matches"], ["mail/docket-D-905.pdf", "no_match"]];
      for (const [ref, reason] of want) {
        const aid = arrivalOf(w, ref);
        if (!aid || filingsFor(w, aid).length !== 0) return false;
        const ex = exceptionsFor(w, aid);
        if (ex.length !== 1 || ex[0].request.reason !== reason) return false;
      }
      const clean = filingsFor(w, arrivalOf(w, "scan/docket-D-883.pdf"));
      if (clean.length !== 1 || clean[0].request.record_id !== "J-1042") return false;
      // every filing sits on the record its printed number names
      return of(w, "file_message").every((c) => {
        const d = w.docs.find((x) => arrivalOf(w, x.ref) === c.request.arrival_id);
        return d && d.content.printed.job === c.request.record_id;
      });
    },
    describe,
  },
  {
    checkId: "keyed-only-when-it-reads-clearly",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = [
        cleanInvoice(T("07:30")),
        invoice("mail/INV-5532.pdf", "email", T("07:35"), { po: "PO-2214", number: "INV-5532", total: undefined, unreadable: ["total"] }),
        invoice("mail/INV-5533.pdf", "email", T("07:40"), { po: "PO-1055", number: "INV-5533", lines: [10000, 20000], total: 33000 }),
      ];
      await deliverAndRun(build, world, world.docs, T("08:00"));
    },
    holds: (w) => {
      const clean = writesFor(w, arrivalOf(w, "mail/INV-5531.pdf"));
      const num = clean.filter((c) => c.request.field === "bill_number");
      const tot = clean.filter((c) => c.request.field === "bill_total");
      if (num.length !== 1 || num[0].request.value !== "INV-5531" || num[0].request.recordId !== "PO-2210") return false;
      if (tot.length !== 1 || tot[0].request.value !== 30000 || tot[0].request.recordId !== "PO-2210") return false;
      for (const [ref, reason] of [["mail/INV-5532.pdf", "unreadable_field"], ["mail/INV-5533.pdf", "does_not_add_up"]]) {
        const aid = arrivalOf(w, ref);
        if (!aid || writesFor(w, aid).length !== 0 || filingsFor(w, aid).length !== 0) return false;
        const ex = exceptionsFor(w, aid);
        if (ex.length !== 1 || ex[0].request.reason !== reason || ex[0].request.field !== "total") return false;
      }
      return of(w, "write_job").every((c) => c.request.recordId === "PO-2210");
    },
    describe,
  },
  {
    checkId: "never-overwrites-the-record",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = [conflictQuote(T("07:30"))];
      await deliverAndRun(build, world, world.docs, T("08:00"));
      world.after = world.ports().readRecord("J-1060"); // read back through the port, in the trace
    },
    holds: (w) => {
      if (w.after?.fields?.quoted_amount !== 480000) return false;
      if (of(w, "write_job").some((c) => c.request.recordId === "J-1060")) return false;
      const ex = exceptionsFor(w, arrivalOf(w, "form/signed-quote-Q-310.pdf"));
      return ex.length === 1 && ex[0].request.reason === "conflicts_with_record" && ex[0].request.field === "quoted_amount" && ex[0].request.document_value === 485000 && ex[0].request.record_value === 480000;
    },
    describe,
  },
  {
    checkId: "filed-once",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      await deliverAndRun(build, world, [invoice("mail/INV-5540.pdf", "email", T("07:40"), { po: "PO-2210", number: "INV-5540" })], T("07:41"));
      await deliverAndRun(build, world, [{ ...invoice("scan/copier-0815.pdf", "scanner", T("08:15"), { po: "PO-2210", number: "INV-5540" }), bytes: "%scan%300dpi:INV-5540 page 1" }], T("08:16"));
    },
    holds: (w) => {
      const first = arrivalOf(w, "mail/INV-5540.pdf");
      const second = arrivalOf(w, "scan/copier-0815.pdf");
      if (!first || !second) return false;
      const inv = of(w, "file_message").filter((c) => c.request.kind === "supplier_invoice");
      if (inv.length !== 1 || inv[0].request.arrival_id !== first || inv[0].request.record_id !== "PO-2210") return false;
      const d = dupsFor(w, second);
      if (d.length !== 1 || d[0].request.duplicate.duplicate_of !== first) return false;
      const writes = of(w, "write_job");
      return writes.filter((c) => c.request.field === "bill_number").length === 1 && writes.filter((c) => c.request.field === "bill_total").length === 1;
    },
    describe,
  },
  {
    checkId: "original-kept-unaltered",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = fiveDoors();
      await deliverAndRun(build, world, world.docs, T("08:45"));
    },
    holds: (w) => {
      if (of(w, "write_file").length !== 0) return false;
      const fs = of(w, "file_message");
      if (fs.length === 0) return false;
      for (const d of w.docs) if (sha256(w.files.get(d.ref).bytes) !== sha256(d.bytes)) return false;
      return fs.every((f) => {
        const c = counts(w).find((x) => x.response.arrival_id === f.request.arrival_id);
        return c && f.request.link === c.request.count.ref && f.request.file_hash === c.request.count.file_hash;
      });
    },
    describe,
  },
  {
    checkId: "one-exceptions-list",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = [
        flyer(T("07:50")),
        conflictQuote(T("07:45")),
        invoice("mail/INV-5533.pdf", "email", T("07:40"), { po: "PO-1055", number: "INV-5533", total: 33000 }),
        invoice("mail/INV-5532.pdf", "email", T("07:35"), { po: "PO-2214", number: "INV-5532", total: undefined, unreadable: ["total"] }),
        ghostDocket(T("07:30")),
        bareSheet(T("07:25")),
        noIdDocket(T("07:20")),
        cleanInvoice(T("07:15")),
      ];
      await deliverAndRun(build, world, world.docs, T("08:00"));
      await close(build, world, "2026-11-02", T("17:00"));
    },
    holds: (w) => {
      const seen = new Set();
      for (const d of w.docs) {
        const aid = arrivalOf(w, d.ref);
        if (!aid) return false;
        if (filingsFor(w, aid).length || dupsFor(w, aid).length) continue;
        const ex = exceptionsFor(w, aid);
        if (ex.length !== 1) return false;
        const { reason, owner } = ex[0].request;
        if (!REASONS.has(reason) || !STAFF.has(owner)) return false;
        seen.add(reason);
      }
      if (seen.size !== REASONS.size) return false;
      const rep = of(w, "publish_report").at(-1)?.request;
      if (!rep || !Array.isArray(rep.open_exceptions) || rep.open_exceptions.length !== 7) return false;
      const since = rep.open_exceptions.map((e) => Date.parse(e.since));
      return since.every((t, i) => i === 0 || since[i - 1] <= t) && rep.open_exceptions.every((e) => STAFF.has(e.owner) && REASONS.has(e.reason));
    },
    describe,
  },
  {
    checkId: "files-and-enters-nothing-else",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = [
        cleanInvoice(T("07:30")),
        invoice("portal/INV-7720.pdf", "supplier_portal", T("07:35"), { po: "PO-2230", number: "INV-7720", lines: [55000], total: 55000 }),
        doc("form/web-302.json", "web_form", T("07:40"), "customer_form", { account: "C-302" }, { email: "lena.ruiz@example.com.au" }),
        doc("portal/S-91-statement.pdf", "supplier_portal", T("07:45"), "statement", { account: "S-91" }, { statement_date: "2026-10-31" }),
        noIdDocket(T("07:50")),
      ];
      await deliverAndRun(build, world, world.docs, T("08:00"));
    },
    holds: (w) => {
      if (of(w, "file_message").length < 4) return false;
      const n = of(w, "notify");
      if (n.length === 0 || !n.every((c) => STAFF.has(c.request.to))) return false;
      return ["send_message", "release_payment", "send_sms", "answer", "talk"].every((p) => of(w, p).length === 0);
    },
    describe,
  },
  {
    checkId: "the-day-closes",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.days = {
        "2026-11-02": [
          cleanInvoice(T("07:40")),
          { ...cleanInvoice(T("08:15"), "scanner", "scan/copier-0815.pdf"), bytes: "%scan%:INV-5531" },
          noIdDocket(T("09:10")),
          flyer(T("10:00")),
          doc("portal/S-88-statement.pdf", "supplier_portal", T("11:30"), "statement", { account: "S-88" }, { statement_date: "2026-10-31" }),
        ],
        "2026-11-03": [],
      };
      await deliverAndRun(build, world, world.days["2026-11-02"], T("12:00"));
      await close(build, world, "2026-11-02", T("17:00"));
      await deliverAndRun(build, world, [], T("09:00", "2026-11-03"));
      await close(build, world, "2026-11-03", T("17:00", "2026-11-03"));
    },
    holds: (w) => {
      const reps = of(w, "publish_report").map((c) => c.request);
      if (reps.length !== 2) return false;
      for (const [day, docs] of Object.entries(w.days)) {
        const r = reps.find((x) => x.day === day);
        if (!r) return false;
        const aids = docs.map((d) => arrivalOf(w, d.ref));
        if (aids.some((a) => !a)) return false;
        const filed = aids.filter((a) => filingsFor(w, a).length).length;
        const dup = aids.filter((a) => dupsFor(w, a).length).length;
        const list = aids.filter((a) => exceptionsFor(w, a).length && !filingsFor(w, a).length).length;
        if (r.arrived !== docs.length || r.filed !== filed || r.duplicates !== dup || r.on_list !== list) return false;
        if (r.arrived !== r.filed + r.on_list + r.duplicates) return false;
      }
      const busy = reps.find((x) => x.day === "2026-11-02");
      return reps.find((x) => x.day === "2026-11-03").arrived === 0 && busy.arrived === 5 && busy.duplicates === 1 && busy.on_list === 2;
    },
    describe,
  },
  {
    checkId: "clearing-is-recorded",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      await deliverAndRun(build, world, [noIdDocket(T("09:10")), conflictQuote(T("09:20"))], T("09:30"));
      await close(build, world, "2026-11-02", T("17:00"));
      const dk = world.exceptionFor("photo/IMG_4471.jpg", "no_id");
      const qt = world.exceptionFor("form/signed-quote-Q-310.pdf", "conflicts_with_record");
      if (!dk || !qt) return;
      // A webhook that fires before anyone has cleared either one: nothing may file.
      world.at(T("08:00", "2026-11-03"));
      for (const ex of [dk, qt]) {
        world.wakeWith({ event: "exception.closed", exception_id: ex.exception_id });
        await build(world.ports());
      }
      world.at(T("08:30", "2026-11-03"));
      world.clear(dk.exception_id, { by: "mick.doyle", recordId: "J-1042" });
      world.clearedAt = { docket: T("08:30", "2026-11-03") };
      world.wakeWith({ event: "exception.closed", exception_id: dk.exception_id });
      await build(world.ports());
      world.at(T("08:45", "2026-11-03"));
      world.clear(qt.exception_id, { by: "priya.shah", value: 485000 });
      world.clearedAt.quote = T("08:45", "2026-11-03");
      world.wakeWith({ event: "exception.closed", exception_id: qt.exception_id });
      await build(world.ports());
      await build(world.ports()); // a repeated webhook changes nothing
    },
    holds: (w) => {
      const dAid = arrivalOf(w, "photo/IMG_4471.jpg");
      const qAid = arrivalOf(w, "form/signed-quote-Q-310.pdf");
      if (!dAid || !qAid || !w.clearedAt) return false;
      const df = filingsFor(w, dAid);
      if (df.length !== 1 || df[0].request.record_id !== "J-1042" || df[0].request.cleared_by !== "mick.doyle") return false;
      if (Date.parse(df[0].at) < Date.parse(w.clearedAt.docket)) return false;
      const qf = filingsFor(w, qAid);
      if (qf.length !== 1 || qf[0].request.record_id !== "J-1060" || Date.parse(qf[0].at) < Date.parse(w.clearedAt.quote ?? "9999-01-01")) return false;
      const qw = of(w, "write_job").filter((c) => c.request.recordId === "J-1060" && c.request.field === "quoted_amount");
      if (qw.length !== 1 || qw[0].request.value !== 485000 || qw[0].request.cleared_by !== "priya.shah") return false;
      const marks = of(w, "evidence").filter((c) => c.request.exception_id);
      const dEx = exceptionId(w, dAid, "no_id");
      const qEx = exceptionId(w, qAid, "conflicts_with_record");
      const mark = (id, by) => marks.filter((c) => c.request.exception_id === id && c.request.cleared_by === by && c.request.cleared_at).length === 1;
      return mark(dEx, "mick.doyle") && mark(qEx, "priya.shah");
    },
    describe,
  },
  {
    checkId: "the-record-by-document",
    world: () => new CostWorld(),
    drive: async (build, world) => {
      world.docs = [cleanInvoice(T("07:40")), { ...cleanInvoice(T("08:15"), "scanner", "scan/copier-0815.pdf"), bytes: "%scan%:INV-5531" }, noIdDocket(T("09:10")), conflictQuote(T("09:20"))];
      await deliverAndRun(build, world, world.docs, T("09:30"));
      await close(build, world, "2026-11-02", T("17:00"));
      world.at(T("08:30", "2026-11-03"));
      const dk = world.exceptionFor("photo/IMG_4471.jpg", "no_id");
      const qt = world.exceptionFor("form/signed-quote-Q-310.pdf", "conflicts_with_record");
      if (dk) {
        world.clear(dk.exception_id, { by: "mick.doyle", recordId: "J-1042" });
        world.wakeWith({ event: "exception.closed", exception_id: dk.exception_id });
        await build(world.ports());
      }
      if (qt) {
        world.clear(qt.exception_id, { by: "priya.shah", value: 485000 });
        world.wakeWith({ event: "exception.closed", exception_id: qt.exception_id });
        await build(world.ports());
      }
      // look each one up through the port, so the read is in the trace
      const p = world.ports();
      world.lookups = Object.fromEntries(world.docs.map((d) => [d.ref, p.lookupDocument(arrivalOf(world, d.ref))]));
    },
    holds: (w) => {
      const expect = {
        "mail/INV-5531.pdf": { record: "PO-2210", dup: false, by: null },
        "scan/copier-0815.pdf": { record: null, dup: true, by: null },
        "photo/IMG_4471.jpg": { record: "J-1042", dup: false, by: "mick.doyle" },
        "form/signed-quote-Q-310.pdf": { record: "J-1060", dup: false, by: "priya.shah" },
      };
      for (const d of w.docs) {
        const e = expect[d.ref];
        const t = w.lookups?.[d.ref];
        if (!Array.isArray(t)) return false;
        const counted = t.find((x) => x.step === "counted");
        if (!counted || counted.door !== d.door || counted.arrived_at !== d.at) return false;
        const kind = t.find((x) => x.step === "kind");
        if (!kind || kind.kind !== d.content.kind) return false;
        if (e.dup) {
          if (!t.some((x) => x.step === "duplicate" && x.duplicate_of === arrivalOf(w, "mail/INV-5531.pdf"))) return false;
          continue;
        }
        const filed = t.find((x) => x.step === "filed");
        if (!filed || filed.record_id !== e.record || !Array.isArray(filed.entered)) return false;
        const real = filingsFor(w, arrivalOf(w, d.ref));
        if (real.length !== 1 || real[0].request.record_id !== filed.record_id) return false;
        if (e.by && !t.some((x) => x.step === "cleared" && x.cleared_by === e.by && x.cleared_at)) return false;
      }
      return true;
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // A precondition: closed by evidence, never scored green by a run.
    world: () => new CostWorld(),
    drive: async () => {},
    holds: () => false,
    describe: () => "No software result. AI Pathway maintains this build in the public repo; the business names who else can explain it and whose account it runs on.",
  },
];

